use customer_behavior;
select* from customer limit 20;
-- 1. Total revenue generated by male vs female customers
select gender, sum('Purchase Amount (USD)') as revenue 
from customer 
group by gender;

-- 2. Which customer used a discount but still spent more than average purchase amount
select `Customer ID`, `Purchase Amount (USD)`
from customer where `Discount Applied` = 'Yes'
and `Purchase Amount (USD)` >= (SELECT AVG(`Purchase Amount (USD)`)
from customer where `Discount Applied` = 'Yes');

  -- 3. Top 5 product with highest average review rating
SELECT `Item Purchased`,
    ROUND(AVG(`Review Rating`), 2) AS average_product_rating
FROM customer
WHERE `Item Purchased` IS NOT NULL
  AND `Review Rating` IS NOT NULL
GROUP BY `Item Purchased`
ORDER BY average_product_rating DESC
LIMIT 5;

-- 4. compare average purchase amounts between standard and express shipping
select `Shipping Type`,
avg(`Purchase Amount (USD)`)
from customer
where `Shipping Type` in ('Standard','Express')
group by `Shipping Type`;

-- 5. do subscribed customers spend more?Compare average spend and total revenue between subscribers and non-subscribers
select `Subscription Status`,
count(`Customer ID`) as total_customers,
round(avg(`Purchase Amount (USD)`),2) as avg_spend,
round(SUM(`Purchase Amount (USD)`),2) as total_revenue
from customer
group by `Subscription Status`
order by total_revenue,avg_spend desc;

-- 6. Which 5 producthave the highest percentage of purchase with discount applied
select `Item Purchased`,
round(100*sum(case when `Discount Applied` = 'Yes' then 1 else 0 end )/count(*),2) as discount_rate
from customer
group by `Item Purchased`
order by discount_rate desc
limit 5;
-- 7. Segment customers into New,Returning, and Loyal based on their total number of previous purchases,and show the count of each segment
with customer_type as(
select `Customer ID`,`Previous Purchases`,
case
when `Previous Purchases` = 1 then 'NEW'
when `Previous Purchases` between 2 and 10 then 'Returning'
else 'Loyal'
end as customer_segment
from customer
)
select customer_segment , count(*) as "Number of Customers"
from customer_type
group by customer_segment;

-- 8.  What are the top 3 most purchased products within each catagory
with item_counts as(
select category,
`Item Purchased`,
count(`Customer ID`) as total_orders,
row_number() over (partition by category order by count(`Customer ID`) desc) as item_rank
from customer
group by `Category`,`Item Purchased`
)
select item_rank,`Category`,`Item Purchased`,total_orders
from item_counts
where item_rank <=3;

-- 9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select `Subscription Status`,
count(`Customer ID`) as repeat_buyers
from customer
where `Previous Purchases` >5
group by `Subscription Status`;

-- 10. Revenue contribution of each age group
select case
when `Age` < 20 then 'Under 20'
when `Age` between 20 and 29 then '20-29'
when `Age` between 30 and 39 then '30-39'
when `Age` between 40 and 49 then '40-49'
else '50+'
end as age_group,
sum(`Purchase Amount (USD)`) as total_revenue
from customer
group by age_group
order by total_revenue desc;


